def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins % item
    return np.where(bins >= item, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_cap = bins - item
    return np.where(remaining_cap >= 0, -remaining_cap, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    counts = bins // item
    remainder = bins % item
    return np.where(mask, counts - remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    counts = np.floor_divide(bins, item, where=mask)
    bonus = np.where(mask & (bins % item == 0), 1, 0)
    return np.where(mask, counts + bonus, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    counts = bins // item
    return np.where(bins >= item, -((counts + 1) * item - bins), -np.inf)
